def get_closest_vowel(word):
    vowels = set("aeiouAEIOU")
    n = len(word)

    # Identify consonants (non-vowels). Note: 'y' is treated as a consonant here based on examples.
    def is_consonant(c):
        return c not in vowels

    # Find the first index from the right that has a vowel between two consonants
    for i in range(n - 1, 0, -1):
        if word[i] in vowels:
            left = i - 1
            right = i + 1

            # Check bounds and conditions
            if left >= 0 and is_consonant(word[left]) and (right < n and is_consonant(word[right])):
                return word[i]

    return ""

